class EnvironmentFactAttribute : Xunit.FactAttribute {
 public EnvironmentFactAttribute() { if (!Enabled) Skip = "Set ENV=1"; }
}
class Tests { [EnvironmentFact] public void Bad() { Assert.Equal(1, 1); } }

class EnvironmentFactAttribute : FactAttribute {
 public EnvironmentFactAttribute() { if (!Enabled) Skip = "defect: tracked issue 123"; }
}
class Tests { [EnvironmentFact] public void Good() { Assert.Equal(1, 1); } }

class BaseFactAttribute : FactAttribute { public BaseFactAttribute() { Skip = "defect: tracked issue 123"; } }
class DerivedAttribute : BaseFactAttribute { }
class Tests { [Derived] public void Bad() { if (flag) return; Assert.Equal(1, 1); } }

